def get_residue_classes(N, k):
    classes = {i: [] for i in range(k)}
    for n in range(1, N + 1):
        remainder = n % k
        if remainder == 0:
            remainder = k  # Use k instead of 0 for the class index, for clearer listing
        classes[remainder - 1].append(n)
    return classes

N = 40
k = 8
classes = get_residue_classes(N, k)
for i in range(k):
    print(f"R_{i+1} (mod {k}): {classes[i]}")
